const initializePostPartsPagination = () => {
		const closeOpenMenus = (activeToggle) => {
			toggles.forEach((toggle) => {
				if (!toggle.isSameNode(activeToggle)) {
					const isOpen = toggle.classList.contains(
						"fqm-post-parts-pagination-toggle__icon--open"
					);

if (isOpen) {
						const pagination = toggle.closest(
							'[data-el="fqm-post-parts-pagination"]'
						);

const list = pagination.querySelector(
							'[data-el="fqm-post-parts-pagination-list"]'
						);

toggle.classList.remove(
							"fqm-post-parts-pagination-toggle__icon--open"
						);
						list.classList.remove("fqm-post-parts-pagination-body--open");
					}
				}
			});
		};

const toggleMenu = (e) => {
			const toggle = e.target;

const pagination = toggle.closest('[data-el="fqm-post-parts-pagination"]');

const list = pagination.querySelector(
				'[data-el="fqm-post-parts-pagination-list"]'
			);

closeOpenMenus(toggle);
			toggle.classList.toggle("fqm-post-parts-pagination-toggle__icon--open");
			list.classList.toggle("fqm-post-parts-pagination-body--open");
		};

const toggles = document.querySelectorAll(
			'[data-el="fqm-post-parts-pagination-toggle"]'
		);

toggles.forEach((toggle) => {
			toggle.addEventListener("click", toggleMenu);
		});
	};

document.addEventListener("DOMContentLoaded", initializePostPartsPagination);

